class Node {
    int val; Node next;
    Node(int v) { val = v; }
}
Node a = new Node(1);
a.next = new Node(2);
a.next.next = new Node(3);
while (a != null) { System.out.print(a.val); a = a.next; }

Node head = new Node(10);
head.next = new Node(20);
head.next.next = new Node(30);
Node n = head;
int pos = 0;
while (n.val != 30) { n = n.next; pos++; }
System.out.println(pos);

Node head = new Node(5);
head.next = new Node(6);
head = head.next;   // old head becomes garbage
System.out.println(head.val);

Node prev = null, cur = head;   // list: 1 -> 2 -> 3
while (cur != null) {
    Node nxt = cur.next;
    cur.next = prev;
    prev = cur;
    cur = nxt;
}
System.out.println(prev.val);

Node a = new Node(1), b = new Node(2), c = new Node(3);
a.next = b; b.next = c; c.next = b;  // cycle back to b
Node slow = a, fast = a;
boolean met = false;
while (fast != null && fast.next != null) {
    slow = slow.next;
    fast = fast.next.next;
    if (slow == fast) { met = true; break; }
}
System.out.println(met);

Node head = new Node(1);
head.next = new Node(3);
Node n = new Node(2);
n.next = head.next;
head.next = n;
System.out.println(head.next.val);

Node head = new Node(1);
head.next = new Node(2);
head.next.next = new Node(3);
head.next = head.next.next;   // unlink value 2
System.out.println(head.next.val);

Node h = new Node(1);
h.next = new Node(2);
h.next.next = new Node(3);
Node p = null, c = h;
while (c != null) { Node t = c.next; c.next = p; p = c; c = t; }
System.out.println(p.next.next.val);
